import{_ as n,l as i,o as e,c as o,v as t,p as s,x as r,d as p,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"资金成本作为 alpha 底","description":"","frontmatter":{"title":"资金成本作为 alpha 底","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/funding-cost-floor.md","filePath":"quant/funding-cost-floor.md","lastUpdated":1789023840000}'),c={name:"quant/funding-cost-floor.md"};function E(u,a,B,A,_,f){const l=i("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="资金成本作为-alpha-底" tabindex="-1">资金成本作为 alpha 底 <a class="header-anchor" href="#资金成本作为-alpha-底" aria-label="Permalink to &quot;资金成本作为 alpha 底&quot;">​</a></h1><div class="epigraph"><p>纸面超额收益要先减去当时占用资金的成本，剩下的才可能是 alpha；成本随保证金、借券、回购与结算占用而变，不是一个常数无风险利率。</p><footer>—— 据 Frazzini and Pedersen, Journal of Financial Economics, 2014；Brunnermeier and Pedersen, 2009 整理</footer></div><p>到上一课<a href="/quant/settlement-cycle">结算周期</a>为止，占用的来源已经拆开：股票维持保证金、强平缺口、借券费、回购 haircut、CCP 保证金、在途结算。本课把它们乘上<strong>当时资金价格</strong>，收成策略的底。后面事件课默认：事件收益若不算资金与可成交约束，只是研究 CAR，不是可交易 alpha。本课不重推各占用公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>因子回测常对超额收益相对市场或相对 Fama–French，分母是名义本金，分子不含融资。Frazzini–Pedersen 的 Betting Against Beta 把杠杆约束放进资产定价：受约束的投资者买高 beta，低 beta 需要杠杆才有吸引力。本课不复制该因子，只用同一思想：没有廉价杠杆，低波动多头与高换手多空的纸面夏普不可实施。缺口是给每条策略路径一条资金账单，账单用 PIT 利率与 PIT 占用，禁止用样本均值利率或用后来的政策利率回填危机月份。</p><p>无风险利率只覆盖「自有现金的机会成本」；杠杆腿还要加信用利差、special 费、保证金利息规则。</p><h3 id="alpha-底不是无风险利率" tabindex="-1">Alpha 底不是无风险利率 <a class="header-anchor" href="#alpha-底不是无风险利率" aria-label="Permalink to &quot;Alpha 底不是无风险利率&quot;">​</a></h3><p>把超额收益定义成 \\(r-r_f\\) 只扣了现金的机会成本，没扣空头借券、没扣 haircut 上升导致的强制去杠杆损失。后者是路径依赖的，不能在期末用一个平均费率相减来替代——去杠杆发生在波动最高的日子，平均费率会低估。本课要求按日：占用\\(_t\\) × 利率\\(_t\\) + 借券费\\(_t\\) + 已实现缺口。</p><p><span class="marginnote">同一策略在自有资金 100% 与杠杆 2 倍下，纸面 alpha 可以相同（若按名义缩放），扣资金后符号可以相反。报告时要声明资金来源。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每日账单至少四项：（1）融资负债 × 当时融资利率；（2）空头市值 × 当时借券费；（3）CCP/期货保证金占用的机会成本或明确的保证金利息；（4）因 haircut/维持线/召回导致的强制交易，按缺口价计入，不摊进「成本率」。求和后从策略收益中扣除，再谈是否覆盖 Fama–French。利率与费率全部 as-of，危机月用危机月的 GC 与 special，不用十年均值。</p><p>若无法得到费率，给出上限/下限两套账单，而不是默认零。零是最强的前视：假设你永远是 GC、永远有无限授信。</p>',12)),(e(),s(d,null,{default:r(()=>[h(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20OCC%5B%22%E5%8D%A0%E7%94%A8%EF%BC%9A%E4%BF%9D%E8%AF%81%E9%87%91%20%E5%9B%9E%E8%B4%AD%20%E7%BB%93%E7%AE%97%22%5D%20--%3E%20BILL%5B%22%E6%8C%89%E6%97%A5%E8%B5%84%E9%87%91%E8%B4%A6%E5%8D%95%22%5D%0A%20%20FEE%5B%22%E5%80%9F%E5%88%B8%E8%B4%B9%22%5D%20--%3E%20BILL%0A%20%20GAP%5B%22%E5%BC%BA%E5%88%B6%E4%BA%A4%E6%98%93%E7%BC%BA%E5%8F%A3%22%5D%20--%3E%20BILL%0A%20%20BILL%20--%3E%20NET%5B%22%E6%89%A3%E8%B4%B9%E5%90%8E%E6%94%B6%E7%9B%8A%22%5D%0A%20%20NET%20--%3E%20ALPHA%5B%22%E6%98%AF%E5%90%A6%E8%BF%98%E6%9C%89%20alpha%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>资金底解释了为何许多异象集中在难融资的一侧：纸面空头赚的是租金加价格，扣费后只剩价格，甚至为负。杠杆约束还改变组合形状：你无法按理论权重持有低保证金消耗与高消耗的名字，于是行业中性、价值多空在实施时偏向易融资端。财务课的质量空头与本课相接：低质量往往 special、haircut 高、公告跳空大，三条账单同时变厚。</p><p><span class="marginnote">后课事件策略换手更高、占用更短、但跳空更频。底的结构不变，只是缺口项权重大于借券项。</span></p><p>按日加总：融资负债×当时融资利率，空头×借券费，保证金占用×机会成本或保证金利息，外加已实现强平/召回缺口。全部 as-of。报告三列：纸面超额、\\(r-r_f\\)、扣完整账单后。零费率只作为对照。杠杆 1× 与杠杆 2× 分开报告，避免把不可得的杠杆夏普写进结论。事件策略同样走这张账单，只是缺口项权重大。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不估计完整的中介资产定价模型，不把本课写成 BAB 因子复制。下一课起对象换成事件日历：业绩公告、并购、指数。后课默认：凡称可交易 alpha，已扣 PIT 资金账单；只报 CAR 的，须标明未扣资金与冲击。</p><p>后课事件策略换手更高，账单结构不变。凡称可交易 alpha，三列收益里至少要有扣完整账单的一列。零费率、常数杠杆、无缺口强平，从本课起视为制度前视，不是「简化假设」。财务质量空头与本课相接：special、高 haircut、公告跳空常同时出现。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>占用来源已拆开；本课乘上当时价格，收成账单。</li><li>\\(r-r_f\\) 不是完整的资金底。</li><li>按日 PIT 计费，不能用均值费率代替路径依赖的去杠杆。</li><li>零费率零 haircut 是最强制度前视。</li><li>事件课开始：研究窗口 ≠ 扣费后的可交易收益。</li><li>出处：Frazzini and Pedersen (2014)；Brunnermeier and Pedersen (2009)；前几课制度文献。</li></ul>',9))])}const C=n(c,[["render",E]]);export{P as __pageData,C as default};
